package com.aoo.bcg.gifting;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
public final class GiftingService {private final JdbcGiftRepository repo;private final GiftingPorts.AssetAuthority assets;private final GiftingPorts.RiskAuthority risk;public GiftingService(JdbcGiftRepository r,GiftingPorts.AssetAuthority a,GiftingPorts.RiskAuthority k){repo=r;assets=a;risk=k;}
 public JdbcGiftRepository.Gift gift(String key,long sender,long recipient,String asset,long quantity,String device,String ip)throws Exception{String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((sender+"|"+recipient+"|"+asset+"|"+quantity).getBytes(StandardCharsets.UTF_8)));var g=repo.reserve(key,sender,recipient,asset,quantity,hash,device,ip,risk.evaluate(sender,recipient,asset,quantity,device,ip));if("COMPLETED".equals(g.state())||"COMPENSATED".equals(g.state()))return g;if(!repo.claim(g.id()))return repo.find(g.id());boolean debited=false,credited=false;try{assets.debit("gift:"+g.id()+":sender-debit",sender,asset,quantity);debited=true;g=repo.transition(g.id(),"PROCESSING","DEBITED",null);assets.credit("gift:"+g.id()+":recipient-credit",recipient,asset,quantity);credited=true;return repo.transition(g.id(),"DEBITED","COMPLETED",null);}catch(Exception failure){try{if(credited)assets.debit("gift:"+g.id()+":recipient-rollback",recipient,asset,quantity);if(debited)assets.credit("gift:"+g.id()+":sender-refund",sender,asset,quantity);repo.transition(g.id(),debited?"DEBITED":"PROCESSING","COMPENSATED","ASSET_AUTHORITY_FAILURE");}catch(Exception compensation){repo.transition(g.id(),debited?"DEBITED":"PROCESSING","COMPENSATION_PENDING","COMPENSATION_FAILED");failure.addSuppressed(compensation);}throw failure;}}
 public JdbcGiftRepository.Gift status(String id,long player){var g=repo.find(id);if(g.sender()!=player&&g.recipient()!=player)throw new SecurityException("gift is not visible to player");return g;}public Object ledger(long player,int limit){return repo.ledger(player,limit);}public Object inbox(long player,long after){return repo.inboundAfter(player,after,50);}}
